-- Vistas de consulta independientes sobre la única base portal360. No duplican datos.
CREATE OR REPLACE VIEW portal_sat_reclamos AS SELECT id,codigo,usuario_id,datos->>'nombre_propietario' AS nombre_propietario,datos->>'dni' AS dni,datos->>'tipo_impuesto' AS tipo_impuesto,datos->>'motivo' AS motivo,NULLIF(datos->>'valor_tasacion','')::numeric AS valor_tasacion,estado,creado_en FROM portal_modulo_items WHERE modulo='sat';
CREATE OR REPLACE VIEW portal_metrobus_recargas AS SELECT id,codigo,usuario_id,datos->>'numero_tarjeta' AS numero_tarjeta,NULLIF(datos->>'monto_recarga','')::numeric AS monto_recarga,COALESCE((datos->>'tarjeta_nueva')::boolean,false) AS tarjeta_nueva,COALESCE((datos->>'pase_universitario')::boolean,false) AS pase_universitario,estado,creado_en FROM portal_modulo_items WHERE modulo='metrobus';
CREATE OR REPLACE VIEW portal_crm_solicitudes AS SELECT id,codigo,usuario_id,datos->>'nombre' AS nombre,datos->>'empresa' AS empresa,datos->>'correo_contacto' AS correo_contacto,NULLIF(datos->>'num_usuarios','')::integer AS num_usuarios,datos->>'mensaje' AS mensaje,estado,creado_en FROM portal_modulo_items WHERE modulo='crm';
CREATE OR REPLACE VIEW portal_agua_reportes AS SELECT id,codigo,usuario_id,datos->>'nombre_vecino' AS nombre_vecino,datos->>'direccion' AS direccion,datos->>'descripcion' AS descripcion,datos->>'zona' AS zona,NULLIF(datos->>'diametro_pulg','')::numeric AS diametro_pulg,datos->>'imagen_url' AS imagen_url,estado,creado_en FROM portal_modulo_items WHERE modulo='agua';
